mapper.select:
SELECT t.*
FROM progress_task t

    INNER JOIN progress_assignee a ON a.task_id = t.id AND a.user_id = #{mineUserId}

WHERE t.workspace_id = #{workspaceId}

    AND t.kind = #{kind}


    AND t.status = #{status}


    AND t.title ILIKE '%' || #{keyword} || '%'


    AND (
        EXISTS (
            SELECT 1 FROM progress_submission s
            WHERE s.task_id = t.id
              AND COALESCE(s.day, CAST(s.created_at AS DATE)) = #{onDate}
        )

            OR t.status NOT IN ('DONE')

    )

ORDER BY t.created_at DESC

SELECT user_id
FROM progress_assignee
WHERE task_id = #{taskId}
